const find=id=>C.find(r=>r.id===id),world=()=>K.exportWorld(),flow=()=>J.getWorkflow(),play=()=>J.getSnapshot();
const EXTRA={calcium:['칼슘','mg'],sodium:['나트륨','mg'],sugar:['당류','g']};
const key=prefix=>prefix+'-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+'-'+(++sequence)+'-'+Math.random().toString(36).slice(2));
let sequence=0,route='home',viewDay=today(),viewMonth=today().slice(0,7),activeItem=null,activeRecipe=null,search='',inventoryKind='all',inventoryZone='all',expiryFilter='',selectedIngredient='',filters={budget:'',time:'',exclude:''},pendingImport=null,photoDraft={product:null,expiry:null,fridge:null},attachment=null,lastStockUndo=null,recipePortions=1,photoPrefill=null,photoReview=null,photoReadController=null,photoReadRun=0,photoReadError='',photoOriginal={product:null,expiry:null,fridge:null},photoInputRun={product:0,expiry:0,fridge:0};
let viewHistory=[],registrationDraft={},lastMealResult=null,itemOrigin=null,purchaseRegistration=null,lastRecognizedValues={};
const pendingForms=new WeakSet();
const zoneNames={freshLeft:'냉장 왼쪽',freshRight:'냉장 오른쪽',frozenLeft:'냉동 왼쪽',frozenRight:'냉동 오른쪽',doorFreshLeft:'냉장 왼쪽 문',doorFreshRight:'냉장 오른쪽 문',doorFrozenLeft:'냉동 왼쪽 문',doorFrozenRight:'냉동 오른쪽 문',seasoning:'냉장고 밖 양념',counter:'냉장고 밖 재료'};
