function scrollState(){const content=$('#trayContent');return [$('#tray'),content,...all('#trayContent *').filter(n=>n.scrollTop||n.scrollLeft)].map(node=>{const path=[];for(let n=node;n&&n!==content&&n!==$('#tray');n=n.parentElement)path.unshift([...n.parentElement.children].indexOf(n));return {node,id:node.id,path,top:node.scrollTop,left:node.scrollLeft};});}
function restoreScroll(rows){for(const r of rows||[]){let node=r.node?.isConnected?r.node:r.id?document.getElementById(r.id):r.path.reduce((n,i)=>n?.children[i],$('#trayContent'));if(node){node.scrollTop=r.top;node.scrollLeft=r.left;}}}
