function cancelRegistration(){rememberDraft();if(!hasRegistration()){resetRegistration();viewHistory=[];K.closeTray();return;}open('재료 등록을 취소할까요?',hint('선택한 사진과 아직 저장하지 않은 입력만 지워요. 냉장고에 저장된 재료는 그대로예요.')+footer(button('계속 작성','back')+button('등록 취소','confirmRegistrationCancel','',true)),'cancelRegistration');}
