async function photoData(file){if(!file||!file.type.startsWith('image/'))throw new Error('이미지 파일을 선택해 주세요.');if(file.size>12*1024*1024)throw new Error('12MB 이하의 이미지를 선택해 주세요.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(new Error('사진을 열 수 없어요. JPG·PNG로 다시 선택해 주세요.'));img.src=url;});const ratio=Math.min(1,420/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.78);if(data.length>=250000)throw new Error('사진 용량이 커요. 더 작은 사진을 선택해 주세요.');return data;}finally{URL.revokeObjectURL(url);}}
